   137|/**
   138| * Detect a vague execution request on public chat — one that has an execution
   139| * verb (fix, deploy, etc.) but no concrete target, error, file, or context.
   140| * Instead of returning a canned auth wall, these should route to the LLM for
   141| * a helpful diagnostic response ("What problem are you seeing?").
   142| */
   143|function isVagueExecutionRequest(message: string): boolean {
   144|  const text = (message ?? '').toLowerCase().trim();
   145|  if (!text || text.length > 500) return false;
   146|
   147|  // Must contain an execution verb
   148|  const hasExecVerb = /\b(?:fix|deploy|patch|commit|push|build|ship|rollback|release|implement|create|update|remove|delete|run)\b/.test(text);
   149|  if (!hasExecVerb) return false;
   150|
   151|  // If there's a concrete target (file name, endpoint, specific bug description,
   152|  // error message, stack trace, SHA), it's NOT vague — block normally.
   153|  const hasConcreteTarget = /\b(?:file|endpoint|route|module|service|component|function|handler|test|bug\s+(?:in|on|at|with)|error[:\s]|stack\s+trace|exception|crash|fail(?:ed|ure)|sha|commit\s+[a-f0-9]|render|supabase|github|database|table|column|500|502|503|timeout|cors|ssl|dns|auth(?:entication|orized)|401|403|404|env\s+var|config)\b/.test(text);
   154|  if (hasConcreteTarget) return false;
   155|
   156|  // Vague patterns: "fix the production problem", "deploy this", "fix it",
   157|  // "build the feature", with no specifics.
   158|  const vaguePatterns = [
   159|    /\bfix\s+(?:the\s+)?(?:production\s+)?(?:problem|issue|bug|error|thing|it|this|that)\b/i,
   160|    /\bdeploy\s+(?:this|that|it|now|live)\b/i,
   161|    /\bpatch\s+(?:this|that|it|the\s+issue)\b/i,
   162|    /\bbuild\s+(?:the\s+)?(?:feature|app|service|module|thing)\b/i,
   163|    /\bimplement\s+(?:this|that|the\s+feature|it)\b/i,
   164|    /\bcreate\s+(?:this|that|it|the\s+module)\b/i,
   165|    /\brollback\s+(?:production|the\s+deploy|it)\b/i,
   166|    /\brun\s+(?:the\s+)?(?:tests|qa|checks|validation)\b/i,
   167|  ];
   168|  return vaguePatterns.some((p) => p.test(text));
   169|}
