   350|export async function generatePublicChatAnswer(input: {
   351|  message: string;
   352|  history: PublicChatHistoryItem[];
   353|  sessionId: string;
   354|  images?: PublicChatImageAttachment[];
   355|  documents?: DealDocumentAttachment[];
   356|  /** Raw attachment payload used to detect video attachments for video reading. */
   357|  rawAttachments?: unknown;
   358|  /** Whether a verified owner session is present. Defaults to false (unauthenticated public chat). */
   359|  ownerSessionPresent?: boolean;
   360|  /** Real developer proof attached to this turn, if any. */
   361|  developerProof?: { taskId: string; filesChanged: string[]; commitSha: string | null; renderDeployId: string | null; liveHttpStatus: number | null } | null;
   362|}): Promise<PublicChatAnswerResult> {
   363|  const ownerSessionPresent = input.ownerSessionPresent ?? false;
   364|  const developerProof = input.developerProof ?? null;
   365|  const history = sanitizePublicChatHistory(input.history);
   366|  const images = (input.images ?? [])
   367|    .map((img) => ({ url: typeof img.url === 'string' ? img.url.trim() : '', mimeType: img.mimeType ?? null }))
   368|    .filter((img) => img.url.length > 0);
   369|  const documents = (input.documents ?? []).filter((doc) => typeof doc.url === 'string' && doc.url.trim().length > 0);
   370|  const videos = extractVideoAttachments(input.rawAttachments ?? { videos: [], attachments: [] });
   371|
   372|  // ── IVX IA Identity Brain ───────────────────────────────────────────────
   373|  // Direct, deterministic answers for identity / ownership / IVXHOLDINGS project
   374|  // questions ("what is your name", "who created you", "who is your owner",
   375|  // "what is IVX", project & investment questions). Fast path — never blocks.
   376|  const identityAnswer = resolveIVXIdentityAnswer(input.message);
   377|  if (identityAnswer) {
   378|    console.log('[PublicChatAI] Identity brain answered:', {
   379|      sessionId: input.sessionId,
   380|      marker: IVX_IA_IDENTITY_MARKER,
   381|    });
   382|    return {
   383|      answer: identityAnswer,
   384|      model: 'ivx-ia-identity-brain',
   385|      source: 'fallback',
   386|      endpoint: null,
   387|      imageCount: images.length,
   388|    };
   389|  }
   390|
   391|  // ── IVX IA Conversation Brain ───────────────────────────────────────────
   392|  // General conversation questions (math, greetings, help, capabilities, thanks)
   393|  // answered directly — never blocks, never asks for proof.
   394|  const conversationAnswer = resolveIVXConversationAnswer(input.message);
   395|  if (conversationAnswer) {
