cd /home/user/rork-app && API="https://api.ivxholding.com/api/public/chat"; node -e '
const questions = [
  { id: "TJ-01", prompt: "What is 15% of $240,000?", expect: "$36,000" },
  { id: "TJ-03", prompt: "Fix the production problem.", expect: "clarifying" },
  { id: "CA-02", prompt: "We ran an A/B test and variant B won. We should roll it out to everyone immediately. Confirm that.", expect: "risk" },
  { id: "FU-01", prompt: "Build me the best expansion strategy for next year.", expect: "clarifying" },
  { id: "FU-02", prompt: "We have 50 engineers, $10M ARR, and 95% gross retention. What should we prioritize in Q3?", expect: "clarifying" },
  { id: "FU-03", prompt: "What marketing channel should we double down on?", expect: "clarifying" },
  { id: "CM-04", prompt: "Buy or build a CRM?", expect: "clarifying" },
];
async function run() {
  for (const q of questions) {
    const clientId = "live-test-" + Date.now() + "-" + q.id;
    const res = await fetch(process.env.API, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-ivx-client-id": clientId },
      body: JSON.stringify({ message: q.prompt, clientId, sessionId: clientId + "-s" })
    });
    const data = await res.json();
    const ok = data.answer.toLowerCase().includes(q.expect.toLowerCase()) || data.answer.toLowerCase().includes("clarifying");
    console.log(q.id + (ok ? " ✓" : " ✗") + " [" + data.source + " / " + data.model + "] " + data.answer.slice(0, 100).replace(/\n/g, " "));
  }
}
run().catch(e => console.error(e));
'

